Here is the class. It uses SQLite storage, serializes writes through an in-memory queue, and reschedules its own alarm every hour. The hourly job is placeholder housekeeping (prune messages older than 30 days and bump a tick counter), so swap in whatever the room actually needs.

```ts
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;
const RETENTION_MS = 30 * 24 * HOUR_MS;

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

export interface ChatMessage {
  id: number;
  author: string;
  body: string;
  createdAt: number;
}

export class ChatRoom extends DurableObject<Env> {
  // Tail of the write queue. Each write starts after the previous one settles.
  #writeTail: Promise<unknown> = Promise.resolve();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          author TEXT NOT NULL,
          body TEXT NOT NULL,
          created_at INTEGER NOT NULL
        )
      `);
      if ((await ctx.storage.getAlarm()) === null) {
        await ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  post(author: string, body: string): Promise<ChatMessage> {
    return this.#serialize(() => {
      const createdAt = Date.now();
      const row = this.ctx.storage.sql
        .exec<{ id: number }>(
          "INSERT INTO messages (author, body, created_at) VALUES (?, ?, ?) RETURNING id",
          author,
          body,
          createdAt,
        )
        .one();
      return { id: row.id, author, body, createdAt };
    });
  }

  history(limit = 50): ChatMessage[] {
    return this.ctx.storage.sql
      .exec<{ id: number; author: string; body: string; created_at: number }>(
        "SELECT id, author, body, created_at FROM messages ORDER BY id DESC LIMIT ?",
        limit,
      )
      .toArray()
      .reverse()
      .map((r) => ({ id: r.id, author: r.author, body: r.body, createdAt: r.created_at }));
  }

  async alarm(): Promise<void> {
    // Schedule the next run before the work, so a failing run still leaves one queued.
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);

    await this.#serialize(async () => {
      this.ctx.storage.sql.exec(
        "DELETE FROM messages WHERE created_at < ?",
        Date.now() - RETENTION_MS,
      );
      const ticks = (await this.ctx.storage.get<number>("ticks")) ?? 0;
      await this.ctx.storage.put("ticks", ticks + 1);
    });
  }

  #serialize<T>(work: () => T | Promise<T>): Promise<T> {
    const run = this.#writeTail.then(() => work());
    this.#writeTail = run.catch(() => undefined);
    return run;
  }
}
```

The wrangler config needs the binding and a SQLite migration, and the compatibility date should be today's:

```jsonc
{
  "compatibility_date": "2026-11-09",
  "durable_objects": {
    "bindings": [{ "name": "CHAT_ROOM", "class_name": "ChatRoom" }]
  },
  "migrations": [{ "tag": "v1", "new_sqlite_classes": ["ChatRoom"] }]
}
```

Callers use `env.CHAT_ROOM.getByName(roomId).post(author, body)`.

